-- relayed by Jump. Steward: catalog-daily/factcheck-venice-2026-11-18.md. One guarded INSERT of the
-- venice.ai row only; no other row is touched. Mirrors the Duck.ai row (manual_override=1, opt_out_available=0).
SELECT 'before_snapshot' AS snapshot, * FROM tools WHERE domain='venice.ai';
INSERT INTO tools (name, domain, compliance_status, summary, data_retention, trains_on_user_data, gdpr_mentioned, source_urls, verified, auto_published, shared_domain, last_checked_at, opt_out_available, manual_override, sourced_from_archive)
SELECT 'Venice AI', 'venice.ai', 'compliant', '"Notwithstanding anything to the contrary, Venice.ai agrees that it shall not use, and shall require that third-party large language model providers (“Third-Party LLM Providers”) do not use, any User Content to train any machine learning, deep learning, or statistical learning algorithms, LLMs, neural networks, or models." Venice''s Terms of Service call themselves a legally binding contract and define User Content as your inputs together with the outputs, so both your prompts and the responses are covered. The promise about outside providers covers third-party LLM (text model) providers only; the Terms don''t say it covers image or video model providers. If you choose to submit feedback, the Terms (§7.4) give Venice a separate unrestricted, perpetual licence to use that feedback for any purpose, including to improve the service; that is not stated as training, and the no-training promise above does not cover feedback. Storage, not training: Venice''s Privacy Policy says it won''t access or store the content of your prompts or outputs, but it stores videos you generate temporarily until you download them. In Anonymous mode, Venice''s privacy page says you should assume the model provider is storing your content. Venice''s API docs say the prompt cache keeps processed inputs for between a few minutes and about an hour. Sources: Venice Terms of Service, last updated 8 June 2026; Privacy Policy, effective 2 June 2026; the privacy page and API docs have no page date. All were checked 18 November 2026.', NULL, 0, NULL, '["https://venice.ai/legal/tos", "https://venice.ai/legal/privacy-policy", "https://venice.ai/privacy", "https://docs.venice.ai/guides/features/prompt-caching"]', 1, 0, 0, '2026-11-18T09:12:00.000Z', 0, 1, 0
WHERE NOT EXISTS (SELECT 1 FROM tools WHERE domain='venice.ai');
SELECT 'after' AS snapshot, domain, compliance_status, manual_override, last_checked_at, source_urls FROM tools WHERE domain='venice.ai';
